@Test
void currentVersionSelector() {
    List<Integer> available = new ArrayList<>();
    Random rnd = new Random(System.nanoTime());
    ClientSession session = Mockito.mock(ClientSession.class);
    for (int expected = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; expected <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; expected++) {
        for (boolean initial : new boolean[] { true, false }) {
            assertEquals(expected, SftpVersionSelector.CURRENT.selectVersion(session, initial, expected, available), "Mismatched directly selected for initial=" + initial + "/available=" + available);
            available.add(expected);
        }
    }
    for (int expected = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; expected <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; expected++) {
        for (boolean initial : new boolean[] { true, false }) {
            for (int index = 0; index < available.size(); index++) {
                Collections.shuffle(available, rnd);
                assertEquals(expected, SftpVersionSelector.CURRENT.selectVersion(session, initial, expected, available), "Mismatched suffling selected for initial=" + initial + ", current=" + expected + ", available=" + available);
            }
        }
    }
}

@Test
void preferredVersionSelector() {
    List<Integer> available = new ArrayList<>();
    for (int version = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; version <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; version++) {
        available.add(version);
    }
    List<Integer> preferred = new ArrayList<>(available);
    List<Integer> unavailable = Arrays.asList(7365, 3777347);
    Random rnd = new Random(System.nanoTime());
    ClientSession session = Mockito.mock(ClientSession.class);
    for (int index = 0; index < preferred.size(); index++) {
        Collections.shuffle(preferred, rnd);
        SftpVersionSelector selector = SftpVersionSelector.preferredVersionSelector(preferred);
        int expected = preferred.get(0);
        for (boolean initial : new boolean[] { true, false }) {
            for (int current = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; current <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; current++) {
                assertEquals(expected, selector.selectVersion(session, initial, current, available), "Mismatched selected for current= " + current + ", available=" + available + ", preferred=" + preferred);
                try {
                    Collections.shuffle(unavailable, rnd);
                    int version = unavailable.get(0);
                    int actual = selector.selectVersion(session, initial, version, unavailable);
                    fail("Unexpected selected version (" + actual + ")" + " for current= " + version + ", available=" + unavailable + ", preferred=" + preferred);
                } catch (IllegalStateException e) {
                    // expected
                }
            }
        }
    }
}

private static void testVersionSelector(SftpVersionSelector selector, int expected) {
    List<Integer> available = new ArrayList<>();
    for (int version = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; version <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; version++) {
        available.add(version);
    }
    Random rnd = new Random(System.nanoTime());
    ClientSession session = Mockito.mock(ClientSession.class);
    for (int current = SftpSubsystemEnvironment.LOWER_SFTP_IMPL; current <= SftpSubsystemEnvironment.HIGHER_SFTP_IMPL; current++) {
        for (boolean initial : new boolean[] { true, false }) {
            for (int index = 0; index < available.size(); index++) {
                assertEquals(expected, selector.selectVersion(session, initial, current, available), "Mismatched selection for current=" + current + ", available=" + available);
                Collections.shuffle(available, rnd);
            }
        }
    }
}

private void testClientProvidersPropagation(Class<?> type, ClientAuthenticationManager client, ClientAuthenticationManager session) throws Exception {
    String baseName = type.getSimpleName();
    outputDebugMessage("testClientProvidersPropagation(%s)", baseName);
    assertTrue(type.isInterface(), baseName + ": not an interface");
    Method getter = ClientAuthenticationManager.class.getMethod("get" + baseName);
    Method setter = ClientAuthenticationManager.class.getMethod("set" + baseName, type);
    Object clientProvider = Mockito.mock(type);
    setter.invoke(client, clientProvider);
    assertSame(clientProvider, getter.invoke(session), baseName + ": mismatched client-only provider");
    Object sessionProvider = Mockito.mock(type);
    setter.invoke(session, sessionProvider);
    assertSame(sessionProvider, getter.invoke(session), baseName + ": mismatched session override provider");
    setter.invoke(session, new Object[] { null });
    assertSame(clientProvider, getter.invoke(session), baseName + ": mismatched nullified session provider");
}

